def migrate_is_cancelled_to_status(apps, schema_editor):
    """Перевести признак отмены в статус: отменён / завершён / запланирован."""
    concert_model = apps.get_model("concerts", "Concert")
    today = date.today()
    updated = []
    for concert in concert_model.objects.all().iterator():
        if concert.is_cancelled:
            concert.status = "CANCELLED"
